import React, { useState, useEffect } from 'react';
import Login from './pages/Login';
import Dashboard from './pages/Dashboard';
import Analytics from './pages/Analytics';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import LoadingSpinner from './components/LoadingSpinner';
import './App.css';

function App() {
  const [token, setToken] = useState(null);
  const [currentPage, setCurrentPage] = useState('dashboard');
  const [stats, setStats] = useState({ total: 0, anomalies: 0, normal: 0 });
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    // Check for existing token on app start
    const savedToken = localStorage.getItem('token');
    if (savedToken) {
      setToken(savedToken);
    }
  }, []);

  const handleSetToken = (newToken) => {
    setToken(newToken);
    if (newToken) {
      localStorage.setItem('token', newToken);
    } else {
      localStorage.removeItem('token');
    }
  };

  if (!token) {
    return <Login setToken={handleSetToken} />;
  }

  return (
    <div className="App">
      {loading && <LoadingSpinner message="Processing..." />}

      <div className="app-layout">
        <Sidebar 
          currentPage={currentPage} 
          setCurrentPage={setCurrentPage}
          onLogout={() => handleSetToken(null)}
        />

        <div className="main-layout">
          <Header currentPage={currentPage} stats={stats} setCurrentPage={setCurrentPage} />

          <main className="main-content">
            {currentPage === 'dashboard' && (
              <Dashboard 
                token={token} 
                setToken={handleSetToken}
                setStats={setStats}
              />
            )}
            {currentPage === 'analytics' && <Analytics token={token} />}
            {currentPage === 'reports' && (
              <div className="page-content">
                <div className="card">
                  <h2>Compliance Reports</h2>
                  <p>Generate detailed compliance and audit reports.</p>
                  <button className="btn">Generate Report</button>
                </div>
              </div>
            )}
            {currentPage === 'settings' && (
              <div className="page-content">
                <div className="card">
                  <h2>System Settings</h2>
                  <p>Configure system preferences and security settings.</p>
                  <button className="btn">Save Settings</button>
                </div>
              </div>
            )}
          </main>
        </div>
      </div>
    </div>
  );
}

export default App;
